// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title HeroCardsMarketplace
 * @notice Fixed-price NFT marketplace for HERO Cards — Architecture Stub (NOT DEPLOYED)
 *
 * @dev Non-custodial listing model. Ownership and approval verified at purchase.
 *      Reentrancy guard on all state-changing functions.
 *      DO NOT DEPLOY without full audit and explicit GO from VIC Foundation.
 *
 * A+ Fixes (2026-06-18):
 *   - buy(): Validate platformFee + royaltyFee <= listing.price before any
 *     transfer to prevent arithmetic underflow DoS.
 *   - buy(): Validate royaltyReceiver != address(0) when royaltyFee > 0 to
 *     prevent funds being silently lost.
 *   - setFee(): Require feeRecipient != address(0) when feeBps > 0 to prevent
 *     platform fees being trapped in the contract.
 *   - list(): Require duration > 0 to prevent zero-duration listings that
 *     expire immediately.
 *   - Added FeesTooHigh custom error for the fee guard.
 */

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/interfaces/IERC2981.sol";

// ─── Errors ───────────────────────────────────────────────────────────────────
error ListingNotActive();
error NotSeller();
error InsufficientPayment();
error NotOwnerOrApproved();
error TransferFailed();
error InvalidPrice();
error ListingExpired();
error InvalidDuration();
error FeesTooHigh();
error InvalidFeeConfig();

contract HeroCardsMarketplace is Ownable2Step, Pausable, ReentrancyGuard {

    // ─── Types ────────────────────────────────────────────────────────────────
    struct Listing {
        address seller;
        address tokenAddress;
        uint256 tokenId;
        uint256 price;
        uint256 expiresAt;
        bool active;
    }

    // ─── State ────────────────────────────────────────────────────────────────
    uint256 public listingCount;
    uint256 public platformFeeBps;   // e.g. 250 = 2.5%
    address public feeRecipient;

    mapping(uint256 => Listing) public listings;

    // ─── Events ───────────────────────────────────────────────────────────────
    event Listed(uint256 indexed listingId, address indexed seller, address tokenAddress, uint256 tokenId, uint256 price, uint256 expiresAt);
    event Cancelled(uint256 indexed listingId);
    event Purchased(uint256 indexed listingId, address indexed buyer, uint256 price);
    event FeeUpdated(uint256 newFeeBps, address newRecipient);

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(uint256 platformFeeBps_, address feeRecipient_) Ownable(msg.sender) {
        // Validate fee config at construction
        if (platformFeeBps_ > 0 && feeRecipient_ == address(0)) revert InvalidFeeConfig();
        platformFeeBps = platformFeeBps_;
        feeRecipient = feeRecipient_;
    }

    // ─── Listing ──────────────────────────────────────────────────────────────

    /**
     * @notice List an NFT for fixed-price sale.
     * @param tokenAddress The ERC-721 contract address.
     * @param tokenId The token ID to list.
     * @param price Sale price in native currency (wei).
     * @param duration Listing duration in seconds. Must be > 0.
     */
    function list(
        address tokenAddress,
        uint256 tokenId,
        uint256 price,
        uint256 duration
    ) external whenNotPaused returns (uint256 listingId) {
        if (price == 0) revert InvalidPrice();
        if (duration == 0) revert InvalidDuration();
        IERC721 token = IERC721(tokenAddress);
        if (token.ownerOf(tokenId) != msg.sender) revert NotOwnerOrApproved();
        // Caller must have approved marketplace before listing
        if (
            token.getApproved(tokenId) != address(this) &&
            !token.isApprovedForAll(msg.sender, address(this))
        ) revert NotOwnerOrApproved();

        listingId = ++listingCount;
        listings[listingId] = Listing({
            seller: msg.sender,
            tokenAddress: tokenAddress,
            tokenId: tokenId,
            price: price,
            expiresAt: block.timestamp + duration,
            active: true
        });

        emit Listed(listingId, msg.sender, tokenAddress, tokenId, price, block.timestamp + duration);
    }

    /**
     * @notice Cancel an active listing. Only the seller can cancel.
     */
    function cancelListing(uint256 listingId) external {
        Listing storage listing = listings[listingId];
        if (!listing.active) revert ListingNotActive();
        if (listing.seller != msg.sender) revert NotSeller();
        listing.active = false;
        emit Cancelled(listingId);
    }

    /**
     * @notice Purchase a listed NFT.
     * Re-checks ownership and approval at purchase time to handle stale listings.
     */
    function buy(uint256 listingId) external payable nonReentrant whenNotPaused {
        Listing storage listing = listings[listingId];
        if (!listing.active) revert ListingNotActive();
        if (block.timestamp > listing.expiresAt) {
            listing.active = false;
            revert ListingExpired();
        }
        if (msg.value < listing.price) revert InsufficientPayment();

        IERC721 token = IERC721(listing.tokenAddress);

        // Re-verify ownership and approval at purchase time
        if (token.ownerOf(listing.tokenId) != listing.seller) {
            listing.active = false;
            revert NotOwnerOrApproved();
        }
        if (
            token.getApproved(listing.tokenId) != address(this) &&
            !token.isApprovedForAll(listing.seller, address(this))
        ) {
            listing.active = false;
            revert NotOwnerOrApproved();
        }

        listing.active = false;

        // Calculate fees
        uint256 platformFee = (listing.price * platformFeeBps) / 10_000;
        uint256 royaltyFee = 0;
        address royaltyReceiver = address(0);

        // ERC-2981 royalty
        try IERC2981(listing.tokenAddress).royaltyInfo(listing.tokenId, listing.price) returns (
            address receiver, uint256 royaltyAmount
        ) {
            royaltyReceiver = receiver;
            royaltyFee = royaltyAmount;
        } catch {}

        // Guard: combined fees must not exceed listing price
        if (platformFee + royaltyFee > listing.price) revert FeesTooHigh();

        // Guard: if royalty fee > 0, receiver must be a valid address
        if (royaltyFee > 0 && royaltyReceiver == address(0)) {
            // Treat as zero royalty — do not subtract from seller proceeds
            royaltyFee = 0;
        }

        uint256 sellerProceeds = listing.price - platformFee - royaltyFee;

        // Transfer NFT before payment (CEI: state change before external calls)
        token.safeTransferFrom(listing.seller, msg.sender, listing.tokenId);

        emit Purchased(listingId, msg.sender, listing.price);

        // Distribute proceeds
        if (platformFee > 0 && feeRecipient != address(0)) {
            (bool ok1, ) = feeRecipient.call{value: platformFee}("");
            if (!ok1) revert TransferFailed();
        }
        if (royaltyFee > 0 && royaltyReceiver != address(0)) {
            (bool ok2, ) = royaltyReceiver.call{value: royaltyFee}("");
            if (!ok2) revert TransferFailed();
        }
        (bool ok3, ) = listing.seller.call{value: sellerProceeds}("");
        if (!ok3) revert TransferFailed();

        // Refund overpayment
        if (msg.value > listing.price) {
            (bool ok4, ) = msg.sender.call{value: msg.value - listing.price}("");
            if (!ok4) revert TransferFailed();
        }
    }

    // ─── Admin ────────────────────────────────────────────────────────────────

    /**
     * @notice Update platform fee configuration.
     * @dev Requires feeRecipient != address(0) when feeBps > 0 to prevent
     *      platform fees being trapped in the contract.
     */
    function setFee(uint256 feeBps, address recipient) external onlyOwner {
        require(feeBps <= 1000, "Fee too high"); // max 10%
        if (feeBps > 0 && recipient == address(0)) revert InvalidFeeConfig();
        platformFeeBps = feeBps;
        feeRecipient = recipient;
        emit FeeUpdated(feeBps, recipient);
    }

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

project/contracts/v2/HeroCardsRewardsDis.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title HeroCardsRewardsDistributor
 * @notice Claim-based holder rewards distributor — Architecture Stub (NOT DEPLOYED)
 *
 * @dev Merkle-root-per-epoch model. No unbounded loops over holders.
 *      Supports native token and/or ERC-20 (HERO) rewards.
 *      DO NOT DEPLOY without full audit and explicit GO from VIC Foundation.
 *
 * A+ Fix (2026-06-18):
 *   - recoverFunds() now uses claimedNative/claimedToken tracking so it only
 *     transfers the remaining (unclaimed) balance and cannot revert due to
 *     prior claims draining the epoch allocation.
 *   - Added EpochRecovered event for off-chain indexing.
 */

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

// ─── Errors ───────────────────────────────────────────────────────────────────
error EpochNotActive();
error AlreadyClaimed();
error InvalidProof();
error EpochAlreadyFinalized();
error RecoveryTooEarly();
error TransferFailed();

contract HeroCardsRewardsDistributor is Ownable2Step, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ─── Types ────────────────────────────────────────────────────────────────
    struct Epoch {
        bytes32 merkleRoot;
        uint256 nativeAmount;       // Total native token (ETH/PLS) allocated
        uint256 tokenAmount;        // Total ERC-20 (HERO) allocated
        uint256 claimedNative;      // Running total of native claimed so far
        uint256 claimedToken;       // Running total of ERC-20 claimed so far
        uint256 startTime;
        uint256 endTime;
        bool finalized;
    }

    // ─── State ────────────────────────────────────────────────────────────────
    IERC20 public heroToken;
    uint256 public epochCount;
    uint256 public constant RECOVERY_DELAY = 90 days;

    mapping(uint256 => Epoch) public epochs;
    /// @dev epochId => wallet => claimed
    mapping(uint256 => mapping(address => bool)) public claimed;

    // ─── Events ───────────────────────────────────────────────────────────────
    event EpochCreated(uint256 indexed epochId, bytes32 merkleRoot, uint256 nativeAmount, uint256 tokenAmount);
    event EpochFinalized(uint256 indexed epochId);
    event Claimed(uint256 indexed epochId, address indexed wallet, uint256 nativeAmount, uint256 tokenAmount);
    event FundsRecovered(uint256 indexed epochId, address indexed to, uint256 nativeAmount, uint256 tokenAmount);

    // ─── Constructor ──────────────────────────────────────────────────────────
    constructor(address heroToken_) Ownable(msg.sender) {
        heroToken = IERC20(heroToken_);
    }

    // ─── Epoch Management ─────────────────────────────────────────────────────

    /**
     * @notice Create a new reward epoch. Funds must be sent with this call (native).
     * @param merkleRoot_ Merkle root of (wallet, nativeAmount, tokenAmount) leaves.
     * @param tokenAmount_ ERC-20 (HERO) amount to allocate (must be pre-approved).
     * @param duration_ Epoch duration in seconds.
     */
    function createEpoch(
        bytes32 merkleRoot_,
        uint256 tokenAmount_,
        uint256 duration_
    ) external payable onlyOwner {
        uint256 epochId = ++epochCount;
        epochs[epochId] = Epoch({
            merkleRoot: merkleRoot_,
            nativeAmount: msg.value,
            tokenAmount: tokenAmount_,
            claimedNative: 0,
            claimedToken: 0,
            startTime: block.timestamp,
            endTime: block.timestamp + duration_,
            finalized: false
        });

        if (tokenAmount_ > 0) {
            heroToken.safeTransferFrom(msg.sender, address(this), tokenAmount_);
        }

        emit EpochCreated(epochId, merkleRoot_, msg.value, tokenAmount_);
    }

    /** @notice Finalize an epoch — root becomes immutable after this. */
    function finalizeEpoch(uint256 epochId) external onlyOwner {
        Epoch storage epoch = epochs[epochId];
        if (epoch.finalized) revert EpochAlreadyFinalized();
        epoch.finalized = true;
        emit EpochFinalized(epochId);
    }

    // ─── Claim ────────────────────────────────────────────────────────────────

    /**
     * @notice Claim rewards for a given epoch.
     * @param epochId The epoch to claim from.
     * @param nativeAmount Native token amount allocated to caller in this epoch.
     * @param tokenAmount ERC-20 (HERO) amount allocated to caller in this epoch.
     * @param proof Merkle proof for (msg.sender, nativeAmount, tokenAmount).
     */
    function claim(
        uint256 epochId,
        uint256 nativeAmount,
        uint256 tokenAmount,
        bytes32[] calldata proof
    ) external nonReentrant whenNotPaused {
        Epoch storage epoch = epochs[epochId];
        if (!epoch.finalized) revert EpochNotActive();
        if (block.timestamp > epoch.endTime) revert EpochNotActive();
        if (claimed[epochId][msg.sender]) revert AlreadyClaimed();

        bytes32 leaf = keccak256(abi.encodePacked(msg.sender, nativeAmount, tokenAmount));
        if (!MerkleProof.verify(proof, epoch.merkleRoot, leaf)) revert InvalidProof();

        // Mark claimed and update running totals before transfers (CEI pattern)
        claimed[epochId][msg.sender] = true;
        epoch.claimedNative += nativeAmount;
        epoch.claimedToken += tokenAmount;
        emit Claimed(epochId, msg.sender, nativeAmount, tokenAmount);

        if (nativeAmount > 0) {
            (bool ok, ) = msg.sender.call{value: nativeAmount}("");
            if (!ok) revert TransferFailed();
        }
        if (tokenAmount > 0) {
            heroToken.safeTransfer(msg.sender, tokenAmount);
        }
    }

    // ─── Recovery ─────────────────────────────────────────────────────────────

    /**
     * @notice Recover unclaimed funds from a finalized, expired epoch.
     * Can only be called RECOVERY_DELAY after epoch end.
     *
     * @dev Uses claimedNative/claimedToken to compute the remaining balance,
     *      so this cannot revert due to prior claims. If all funds were claimed,
     *      the remaining amounts are zero and no transfer is attempted.
     */
    function recoverFunds(uint256 epochId, address to) external onlyOwner {
        Epoch storage epoch = epochs[epochId];
        if (!epoch.finalized) revert EpochNotActive();
        if (block.timestamp < epoch.endTime + RECOVERY_DELAY) revert RecoveryTooEarly();

        // Compute remaining (unclaimed) balances
        uint256 remainingNative = epoch.nativeAmount - epoch.claimedNative;
        uint256 remainingTokens = epoch.tokenAmount - epoch.claimedToken;

        // Zero out to prevent double-recovery
        epoch.claimedNative = epoch.nativeAmount;
        epoch.claimedToken = epoch.tokenAmount;

        emit FundsRecovered(epochId, to, remainingNative, remainingTokens);

        if (remainingNative > 0) {
            (bool ok, ) = to.call{value: remainingNative}("");
            if (!ok) revert TransferFailed();
        }
        if (remainingTokens > 0) {
            heroToken.safeTransfer(to, remainingTokens);
        }
    }

    // ─── Admin ────────────────────────────────────────────────────────────────

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    receive() external payable {}
}

